SELECT CASE WHEN rating >= 4.6 THEN 'HIGH' ELSE 'LOW' END AS rating_tier, city, SORT_ARRAY(COLLECT_SET(country)) AS country_list, COUNT(DISTINCT city) AS distinct_cities, PERCENTILE_APPROX(rating, 0.5) AS rating_p50, PERCENT_RANK() OVER (PARTITION BY CASE WHEN rating >= 4.6 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(DISTINCT city) DESC) AS distinct_cities_percent_rank FROM suppliers GROUP BY 1, 2 ORDER BY city DESC NULLS FIRST
